// AUTO-GENERATED base - Classic product data (Signature-style structure).
export type ProductData = {
  name: string
  categoryLabel: string
  tagline: string
  story: [string, string]
  details: { label: string; value: string }[]
  sizes: string[]
  unit: string
  heroImg: string
  storyImg: string
  // Optional - richer fields used by Windows & Doors "system" product pages
  description?: string
  certification?: string
  configurations?: string[]
  profiles?: { label: string; value: string }[]
  performance?: string[]
  glassOptions?: string[]
  finishOptions?: string[]
  gallery?: string[]
  projectExample?: { title: string; location: string; desc: string; img: string }
  // Optional - Bathroom "package style" product pages (fixed inclusions + configurable options)
  packageStyle?: string
  fixedInclusions?: { label: string; value: string }[]
  // Optional - short feature line shown under the tagline on joinery range cards
  features?: string
  // Optional - interactive hotspot image (Admin > Products)
  hotspots?: HotspotBlock
  // Optional - page blocks (Admin > Products), JSON
  blocks?: string
  /** Shown on the card as "Coming soon"; the card does not open a page. */
  comingSoon?: boolean
}

export type CategoryMeta = {
  label: string
  headline: string
  body: string[]
  /** Optional Story-section copy; falls back to `body` when absent (keeps hero intro independent) */
  story?: string[]
  heroImg: string
  storyImg: string
}

export const CATEGORY_META: Record<string, CategoryMeta> = {
  "windows-doors": { label: "Windows & Doors", headline: "The Classic Collection.", body: ["The Atelier Classic Collection brings together architectural aluminium window and door systems, precise specification and project-specific manufacturing for new homes, renovations and residential developments.", "Designed around your architectural plans, every package is tailored to the project - from opening configurations and glazing through to frame finishes, hardware and performance requirements. The result is a complete window and door package that looks refined, performs as required and arrives ready for the next stage of your build."], story: ["Classic is our curated range for projects that demand clean design, dependable performance and flexibility without unnecessary complexity.", "From fixed and awning windows to expansive sliding and stacking door systems, each element is selected and configured around the architecture of the home. Opening sizes, panel configurations, glazing, wind classification, energy performance, hardware and powdercoat finishes are resolved as one coordinated package.", "Rather than selecting an off-the-shelf window and adapting the project around it, we specify the system around the project. Every system is specified to comply with AS 2047, AS 1288 and the project's BASIX or NatHERS requirements."], heroImg: "/window-hero.png", storyImg: "/Atelier_Classic.png" },
  "joinery": { label: "Custom Joinery", headline: "Made for the home you're building.", body: ["Joinery that combines refined proportions, premium materials and precise detailing - designed to your project and made to fit as built."], story: ["Premium materials, precise detailing and finishes selected to work together. Statement kitchens, butler's pantries, wardrobes, laundries, bathroom cabinetry and automated joinery - each piece made specifically for your project and installed by the Atelier team.", "Every package is developed around your architectural plans, the material palette and how the space will actually be used, then documented in shop drawings before manufacture - with standard construction tolerances built into the detailing. Renovating? We design around your existing room, working from a measured drawing or your builder's dimensions, verified before anything is made.", "Custom joinery, done the way construction actually happens."], heroImg: "/joinery-hero.png", storyImg: "/joinery-story.png" },
  "bathrooms": { label: "Bathroom Packages", headline: "Five fully coordinated bathrooms.", body: ["Complete, coordinated bathroom packages in five distinct styles - every fixture, finish and surface selected to work together as one considered whole.", "Choose your style, then tailor the vanity, toilet, tiling and supply or install to suit your project. Final individual-product and complete-room photography will follow."], heroImg: "/bathroom-hero.png", storyImg: "/Atelier_Classic.png" },
}

