export function getProduct(category: string, product: string): ProductData | null {
  return ALL_PRODUCTS[category]?.[product] ?? null
}

export function listProducts(category: string): { slug: string; data: ProductData }[] {
  const c = ALL_PRODUCTS[category]
  if (!c) return []
  return Object.entries(c).map(([slug, data]) => ({ slug, data }))
}

/** Bathroom package-style products (those with a fixed `packageStyle`). */
export function listPackages(category: string): { slug: string; data: ProductData }[] {
  return listProducts(category).filter((p) => p.data.packageStyle)
}

/** Non-package component products (the "included products" library). */
export function listComponents(category: string): { slug: string; data: ProductData }[] {
  return listProducts(category).filter((p) => !p.data.packageStyle)
}

export const CLASSIC_CATEGORIES = Object.keys(CATEGORY_META)

// Windows & Doors product families - group the systems into platforms.
export type WdFamily = { slug: string; name: string; tagline: string; desc: string; slugs: string[] }
export const WD_FAMILIES: WdFamily[] = [
  { slug: "series-102", name: "Series 102", tagline: "Our most versatile Classic platform.", desc: "Built around a robust 102mm aluminium system, Series 102 brings sliding, awning, casement, pocket sliding and louvre configurations into one coordinated family. Designed for larger openings, generous glazing and contemporary Australian homes, it gives projects the flexibility to maintain a consistent architectural language across multiple window and door types.", slugs: ["asg-series-102", "asg-102-awning", "asg-102-casement", "asg-102-pocket", "asg-102-louvre"] },
  { slug: "series-86", name: "Series 86", tagline: "Streamlined performance for everyday spaces.", desc: "Series 86 is a clean, space-efficient aluminium platform designed for practical residential applications. Available in sliding and awning configurations, its slimmer 86mm system provides dependable everyday performance while maximising natural light and preserving valuable internal and external space.", slugs: ["asg-series-86", "asg-86-awning"] },
  { slug: "series-75", name: "Series 75", tagline: "Designed to open the home completely.", desc: "Series 75 is our dedicated folding door platform, created for projects seeking a broad, uninterrupted connection between indoor and outdoor living. Multiple glazed panels fold and stack neatly to the side, allowing living, dining and alfresco spaces to operate as one connected environment.", slugs: ["asg-series-75"] },
  { slug: "series-101", name: "Series 101", tagline: "Classic proportions with practical vertical ventilation.", desc: "Series 101 brings the timeless character of a hung window into a contemporary aluminium system. Available in single- or double-hung configurations, its vertical sliding operation provides natural ventilation without projecting into internal rooms, walkways or landscaped areas.", slugs: ["asg-series-101"] },
]
export function getFamily(slug: string): WdFamily | null {
  return WD_FAMILIES.find((f) => f.slug === slug) ?? null
}
